/* Keep DLL replacements separate from the game-executable inventory. */
struct bb_qmixer_hook {
  uintptr_t address;
#ifndef BB_QMIX_ENTRIES_ONLY
  const unsigned char *signature;
  size_t size;
#endif
  void (*replacement)(void);
};
#ifdef BB_QMIX_ENTRIES_ONLY
/* Native entry mappings contain only C targets; original instruction signatures are
 * needed only when the Windows bridge patches an existing DLL. */
#define BB_QMIX_HOOK(address, function, ...)                                   \
  {address, (void (*)(void))function}
#else
#define BB_QMIX_HOOK(address, function, ...)                                   \
  {address, (const unsigned char[]){__VA_ARGS__},                              \
   sizeof((const unsigned char[]){__VA_ARGS__}), (void (*)(void))function}
#endif
